#!/usr/bin/env python3
from pathlib import Path
import base64,re
ROOT=Path.cwd()
changed=[]
def read(path):
    p=ROOT/path
    if not p.exists(): raise SystemExit(f"Fichier introuvable : {path}. Lance ce script depuis la racine du dépôt.")
    return p.read_text(encoding="utf-8")
def write(path,content):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding="utf-8")
    if path not in changed: changed.append(path)
def rep(path,old,new,label):
    content=read(path)
    if new in content and old not in content:return
    if old not in content:raise SystemExit(f"Motif introuvable pour {label} dans {path}")
    write(path,content.replace(old,new,1))
def full(path,b64):
    write(path,base64.b64decode(b64).decode("utf-8"))
